1	// This file implements the organization-scoped audit chain. Every
2	// successful publish and rollback, and every Decide that names a
3	// decision organization, is appended to a per-organization sequence of
4	// records linked by SHA-256 fingerprints. Records store detached
5	// copies, so requests, policies or query results mutated after the fact
6	// can never rewrite history. The chain can be paged, exported up to a
7	// frozen sequence range, and verified offline against an out-of-band
8	// (organization, up-to-sequence, fingerprint) basis.
9	package darksafe
10	
11	import (
12		"crypto/sha256"
13		"encoding/hex"
14		"encoding/json"
15		"errors"
16		"fmt"
17		"reflect"
18	)
19	
20	// AuditCategory classifies an audit record.
21	type AuditCategory string
22	
23	const (
24		// AuditPolicyChange marks a publish or rollback that produced a new
25		// policy version.
26		AuditPolicyChange AuditCategory = "policy_change"
27		// AuditDecision marks a Decide that named a decision organization,
28		// including denials.
29		AuditDecision AuditCategory = "decision"
30	)
31	
32	// AuditRecord is one immutable entry in an organization's audit chain.
33	// Seq is the organization-local, 1-based consecutive number. Each record
34	// carries the fingerprint of the preceding record, which links the chain.
35	type AuditRecord struct {
36		Org             string        `json:"org"`
37		Seq             int           `json:"seq"`
38		Category        AuditCategory `json:"category"`
39		Version         int           `json:"version"`
40		SourceVersion   int           `json:"source_version,omitempty"`
41		Policies        []Policy      `json:"policies,omitempty"`
42		Request         OrgRequest    `json:"request"`
43		Decision        Decision      `json:"decision"`
44		PrevFingerprint string        `json:"prev_fingerprint"`
45		Fingerprint     string        `json:"fingerprint"`
46	}
47	
48	// AuditQuery pages through an organization's audit chain in ascending
49	// sequence order. The first query leaves UpToSeq and Fingerprint at zero,
50	// which freezes the range at the current tail; later queries must echo
51	// that range so records appended in the meantime do not mix in.
52	type AuditQuery struct {
53		PageSize    int           `json:"page_size"`
54		UpToSeq     int           `json:"up_to_seq"`
55		Fingerprint string        `json:"fingerprint"`
56		AfterSeq    int           `json:"after_seq"`
57		Category    AuditCategory `json:"category,omitempty"`
58		Subject     string        `json:"subject,omitempty"`
59	}
60	
61	// AuditPage is one page of an audit query. NextSeq is zero when the
62	// frozen range is exhausted.
63	type AuditPage struct {
64		Org         string        `json:"org"`
65		UpToSeq     int           `json:"up_to_seq"`
66		Fingerprint string        `json:"fingerprint"`
67		Records     []AuditRecord `json:"records"`
68		NextSeq     int           `json:"next_seq"`
69	}
70	
71	// AuditExport is a self-contained package for offline verification. The
72	// caller keeps Org, UpToSeq and Fingerprint out of band as the trusted
73	// basis; the records can then be verified without the original Store.
74	type AuditExport struct {
75		Org         string        `json:"org"`
76		UpToSeq     int           `json:"up_to_seq"`
77		Fingerprint string        `json:"fingerprint"`
78		Records     []AuditRecord `json:"records"`
79	}
80	
81	// Sentinel errors so callers can distinguish failure causes with errors.Is.
82	var (
83		// ErrAuditNotFound means the requested audit sequence does not exist.
84		ErrAuditNotFound = errors.New("darksafe: audit record not found")
85		// ErrAuditNotDecision means reverify was asked for a non-decision record.
86		ErrAuditNotDecision = errors.New("darksafe: audit record is not a decision")
87		// ErrInvalidAuditQuery means a query or export range is invalid.
88		ErrInvalidAuditQuery = errors.New("darksafe: invalid audit query")
89		// ErrAuditFingerprint means the echoed range fingerprint does not match
90		// the chain at that sequence.
91		ErrAuditFingerprint = errors.New("darksafe: audit fingerprint mismatch")
92		// ErrAuditVerification means an export failed offline verification.
93		ErrAuditVerification = errors.New("darksafe: audit verification failed")
94	)
95	
96	// clonePolicies returns a detached copy of a policy slice.
97	func clonePolicies(ps []Policy) []Policy {
98		if ps == nil {
99			return nil
100		}
101		out := make([]Policy, len(ps))
102		copy(out, ps)
103		return out
104	}
105	
106	// cloneRequest returns a detached copy of a request, including its
107	// subject roles. A nil roles slice stays nil and a non-nil one stays
108	// non-nil, so detached copies compare equal to the originals.
109	func cloneRequest(r OrgRequest) OrgRequest {
110		if r.Subject.Roles != nil {
111			cp := make([]string, len(r.Subject.Roles))
112			copy(cp, r.Subject.Roles)
113			r.Subject.Roles = cp
114		}
115		return r
116	}
117	
118	// cloneDecision returns a detached copy of a decision, including its
119	// matched policy ids. A nil matched slice stays nil and a non-nil one
120	// stays non-nil, so detached copies compare equal to the originals.
121	func cloneDecision(d Decision) Decision {
122		if d.Matched != nil {
123			cp := make([]string, len(d.Matched))
124			copy(cp, d.Matched)
125			d.Matched = cp
126		}
127		return d
128	}
129	
130	// cloneRecord returns a deep copy of a record.
131	func cloneRecord(r *AuditRecord) *AuditRecord {
132		out := *r
133		out.Policies = clonePolicies(r.Policies)
134		out.Request = cloneRequest(r.Request)
135		out.Decision = cloneDecision(r.Decision)
136		return &out
137	}
138	
139	// auditCanonical is the deterministic input to the fingerprint. Struct
140	// field order is fixed and no maps are used, so json.Marshal is stable
141	// across runs and processes.
142	type auditCanonical struct {
143		Org             string
144		Seq             int
145		Category        string
146		Version         int
147		SourceVersion   int
148		Policies        []Policy
149		Request         OrgRequest
150		Decision        Decision
151		PrevFingerprint string
152	}
153	
154	// computeFingerprint links a record to the preceding one: it hashes the
155	// record's canonical content together with the previous fingerprint.
156	func computeFingerprint(prev string, r *AuditRecord) string {
157		in := auditCanonical{
158			Org: r.Org, Seq: r.Seq, Category: string(r.Category),
159			Version: r.Version, SourceVersion: r.SourceVersion,
160			Policies: r.Policies, Request: r.Request, Decision: r.Decision,
161			PrevFingerprint: prev,
162		}
163		b, err := json.Marshal(in)
164		if err != nil {
165			// All fields are JSON-safe types; this is unreachable.
166			panic(err)
167		}
168		sum := sha256.Sum256(b)
169		return hex.EncodeToString(sum[:])
170	}
171	
172	// appendRecordLocked appends a record to the organization's chain,
173	// assigning the next sequence number and linking fingerprints. The
174	// caller must hold s.mu.
175	func (s *Store) appendRecordLocked(st *orgState, r *AuditRecord) {
176		r.Seq = len(st.audit) + 1
177		r.PrevFingerprint = ""
178		if r.Seq > 1 {
179			r.PrevFingerprint = st.audit[r.Seq-2].Fingerprint
180		}
181		r.Fingerprint = computeFingerprint(r.PrevFingerprint, r)
182		st.audit = append(st.audit, r)
183	}
184	
185	// auditTailLocked returns the current record count and the fingerprint
186	// of the last record ("" for an empty chain). The caller must hold s.mu.
187	func auditTailLocked(st *orgState) (int, string) {
188		if st == nil || len(st.audit) == 0 {
189			return 0, ""
190		}
191		return len(st.audit), st.audit[len(st.audit)-1].Fingerprint
192	}
193	
194	// matches reports whether a record passes the query's filters. A subject
195	// filter implies decision records only, since policy changes carry no
196	// subject.
197	func (q AuditQuery) matches(r *AuditRecord) bool {
198		if q.Subject != "" {
199			if r.Category != AuditDecision || r.Request.Subject.ID != q.Subject {
200				return false
201			}
202		}
203		if q.Category != "" && r.Category != q.Category {
204			return false
205		}
206		return true
207	}
208	
209	// AuditQuery returns one page of the organization's audit chain, paged
210	// in ascending sequence order. The first query (UpToSeq zero) freezes
211	// the range at the current tail; later queries echo UpToSeq and
212	// Fingerprint from the first page and continue after AfterSeq, so
213	// concurrently appended records never mix in.
214	func (s *Store) AuditQuery(org string, q AuditQuery) (AuditPage, error) {
215		if org == "" {
216			return AuditPage{}, ErrMissingOrganization
217		}
218		if q.PageSize <= 0 {
219			return AuditPage{}, fmt.Errorf("%w: page size must be positive, got %d", ErrInvalidAuditQuery, q.PageSize)
220		}
221		if q.UpToSeq < 0 {
222			return AuditPage{}, fmt.Errorf("%w: upToSeq must not be negative, got %d", ErrInvalidAuditQuery, q.UpToSeq)
223		}
224		if q.AfterSeq < 0 {
225			return AuditPage{}, fmt.Errorf("%w: afterSeq must not be negative, got %d", ErrInvalidAuditQuery, q.AfterSeq)
226		}
227		if q.Category != "" && q.Category != AuditPolicyChange && q.Category != AuditDecision {
228			return AuditPage{}, fmt.Errorf("%w: unknown category %q", ErrInvalidAuditQuery, q.Category)
229		}
230		s.mu.Lock()
231		defer s.mu.Unlock()
232		st := s.orgs[org]
233		tail, _ := auditTailLocked(st)
234	
235		upTo := q.UpToSeq
236		if upTo == 0 {
237			upTo = tail
238		} else if upTo > tail {
239			return AuditPage{}, fmt.Errorf("%w: upToSeq %d exceeds %d existing records", ErrInvalidAuditQuery, upTo, tail)
240		}
241		if q.AfterSeq > upTo {
242			return AuditPage{}, fmt.Errorf("%w: afterSeq %d is beyond upToSeq %d", ErrInvalidAuditQuery, q.AfterSeq, upTo)
243		}
244		wantFP := ""
245		if st != nil && upTo > 0 {
246			wantFP = st.audit[upTo-1].Fingerprint
247		}
248		if q.UpToSeq != 0 && q.Fingerprint != wantFP {
249			return AuditPage{}, fmt.Errorf("%w: fingerprint at seq %d does not match", ErrAuditFingerprint, upTo)
250		}
251	
252		page := AuditPage{Org: org, UpToSeq: upTo, Fingerprint: wantFP}
253		for seq := q.AfterSeq + 1; seq <= upTo; seq++ {
254			r := st.audit[seq-1]
255			if !q.matches(r) {
256				continue
257			}
258			if len(page.Records) < q.PageSize {
259				page.Records = append(page.Records, *cloneRecord(r))
260				// NextSeq is the last returned sequence; the caller passes
261				// it as AfterSeq to continue.
262				page.NextSeq = seq
263				continue
264			}
265			// The page is full and at least one more matching record exists.
266			return page, nil
267		}
268		// The frozen range is exhausted.
269		page.NextSeq = 0
270		return page, nil
271	}
272	
273	// AuditExport returns detached copies of all records with sequence
274	// numbers 1..upToSeq, together with the tail fingerprint, for offline
275	// verification. upToSeq may be zero, which exports an empty chain.
276	func (s *Store) AuditExport(org string, upToSeq int) (AuditExport, error) {
277		if org == "" {
278			return AuditExport{}, ErrMissingOrganization
279		}
280		if upToSeq < 0 {
281			return AuditExport{}, fmt.Errorf("%w: upToSeq must not be negative, got %d", ErrInvalidAuditQuery, upToSeq)
282		}
283		s.mu.Lock()
284		defer s.mu.Unlock()
285		st := s.orgs[org]
286		tail, _ := auditTailLocked(st)
287		if upToSeq > tail {
288			return AuditExport{}, fmt.Errorf("%w: upToSeq %d exceeds %d existing records", ErrInvalidAuditQuery, upToSeq, tail)
289		}
290		exp := AuditExport{Org: org, UpToSeq: upToSeq}
291		if upToSeq > 0 {
292			exp.Fingerprint = st.audit[upToSeq-1].Fingerprint
293		}
294		exp.Records = make([]AuditRecord, upToSeq)
295		for i := 0; i < upToSeq; i++ {
296			exp.Records[i] = *cloneRecord(st.audit[i])
297		}
298		return exp, nil
299	}
300	
301	// policiesForVersion finds the policy-change record that created the
302	// given version and returns its full policy set. Version 0 has no
303	// policy set.
304	func policiesForVersion(records []AuditRecord, version int) ([]Policy, error) {
305		if version == 0 {
306			return nil, nil
307		}
308		for i := range records {
309			r := &records[i]
310			if r.Category == AuditPolicyChange && r.Version == version {
311				return r.Policies, nil
312			}
313		}
314		return nil, fmt.Errorf("no policy change record creates version %d", version)
315	}
316	
317	// recomputeDecision restores the decision for a request under the given
318	// version's policies, mirroring Decide. Version 0 is the pre-publish
319	// denial.
320	func recomputeDecision(org string, req OrgRequest, version int, policies []Policy) Decision {
321		if d, ok := checkRequest(org, req); !ok {
322			return d
323		}
324		if version == 0 {
325			return Decision{Allowed: false, Reason: "organization has no published version"}
326		}
327		return evaluate(req, policies, version)
328	}
329	
330	// VerifyAuditExport verifies an export offline, without the original
331	// Store. It checks that the record count matches UpToSeq, that sequence
332	// numbers are exactly 1..N, that every record belongs to the export's
333	// organization, that every fingerprint links to its predecessor, and
334	// that every decision record is the correct outcome for its request
335	// under the policy version it names. The caller must separately trust
336	// Org, UpToSeq and the tail Fingerprint; any field mutation, deleted
337	// middle or tail record, swapped order, or spliced-in record fails.
338	func VerifyAuditExport(exp AuditExport) error {
339		if exp.Org == "" {
340			return ErrMissingOrganization
341		}
342		if exp.UpToSeq < 0 {
343			return fmt.Errorf("%w: upToSeq must not be negative", ErrInvalidAuditQuery)
344		}
345		if len(exp.Records) != exp.UpToSeq {
346			return fmt.Errorf("%w: declared %d records but found %d", ErrAuditVerification, exp.UpToSeq, len(exp.Records))
347		}
348		prev := ""
349		for i := range exp.Records {
350			r := &exp.Records[i]
351			if r.Seq != i+1 {
352				return fmt.Errorf("%w: record %d has sequence %d", ErrAuditVerification, i+1, r.Seq)
353			}
354			if r.Org != exp.Org {
355				return fmt.Errorf("%w: record %d belongs to organization %q", ErrAuditVerification, r.Seq, r.Org)
356			}
357			if r.Category != AuditPolicyChange && r.Category != AuditDecision {
358				return fmt.Errorf("%w: record %d has unknown category %q", ErrAuditVerification, r.Seq, r.Category)
359			}
360			fp := computeFingerprint(prev, r)
361			if fp != r.Fingerprint {
362				return fmt.Errorf("%w: fingerprint mismatch at record %d", ErrAuditVerification, r.Seq)
363			}
364			prev = fp
365			if r.Category == AuditDecision {
366				policies, err := policiesForVersion(exp.Records, r.Version)
367				if err != nil {
368					return fmt.Errorf("%w: record %d: %v", ErrAuditVerification, r.Seq, err)
369				}
370				want := recomputeDecision(exp.Org, r.Request, r.Version, policies)
371				if !reflect.DeepEqual(want, r.Decision) {
372					return fmt.Errorf("%w: record %d: decision does not match version %d", ErrAuditVerification, r.Seq, r.Version)
373				}
374			}
375		}
376		if prev != exp.Fingerprint {
377			return fmt.Errorf("%w: tail fingerprint mismatch", ErrAuditVerification)
378		}
379		return nil
380	}
381	
382	// ReverifyDecision restores the original result of a past Decide using
383	// the request and policy version stored in the decision record with the
384	// given organization-local sequence. Later publishes or rollbacks do
385	// not affect the conclusion. A non-decision record returns
386	// ErrAuditNotDecision; a sequence that does not exist returns
387	// ErrAuditNotFound. Reverify is read-only and creates no records.
388	func (s *Store) ReverifyDecision(org string, seq int) (Decision, error) {
389		if org == "" {
390			return Decision{}, ErrMissingOrganization
391		}
392		if seq < 1 {
393			return Decision{}, fmt.Errorf("%w: sequence %d", ErrAuditNotFound, seq)
394		}
395		s.mu.Lock()
396		defer s.mu.Unlock()
397		st := s.orgs[org]
398		if st == nil || seq > len(st.audit) {
399			return Decision{}, fmt.Errorf("%w: organization %q has no audit record %d", ErrAuditNotFound, org, seq)
400		}
401		rec := st.audit[seq-1]
402		if rec.Category != AuditDecision {
403			return Decision{}, fmt.Errorf("%w: record %d is %q, not a decision", ErrAuditNotDecision, seq, rec.Category)
404		}
405		var policies []Policy
406		if rec.Version >= 1 {
407			src, ok := st.versions[rec.Version]
408			if !ok {
409				return Decision{}, fmt.Errorf("%w: version %d no longer exists", ErrAuditVerification, rec.Version)
410			}
411			policies = append([]Policy(nil), src...)
412		}
413		return recomputeDecision(org, rec.Request, rec.Version, policies), nil
414	}
